books = [
    {"title": "The Great Adventure", "author": "Jane Smith", "isbn": "123456", "copies_available": 3},
    {"title": "Data Science 101", "author": "John Doe", "isbn": "789012", "copies_available": 0},
    {"title": "Python Basics", "author": "Alice Johnson", "isbn": "345678", "copies_available": 5}
]

users = [
    {"user_id": "123", "name": "Bob Wilson", "current_loans": 2},
    {"user_id": "456", "name": "Eva Brown", "current_loans": 1}
]

# Mocked functions
def search_books(title: str) -> list:
    """Return books matching the title."""
    return [book for book in books if book["title"].lower() == title.lower()]

def check_availability(isbn: str) -> int:
    """Return the number of available copies for a given ISBN."""
    book = next((b for b in books if b["isbn"] == isbn), None)
    return book["copies_available"] if book else 0

def borrow_book(user_id: str, isbn: str) -> str:
    """Attempt to borrow a book and return the due date or an error message."""
    user = next((u for u in users if u["user_id"] == user_id), None)
    book = next((b for b in books if b["isbn"] == isbn), None)

    if not user or not book:
        return "Invalid user or book"
    if user["current_loans"] >= 3:
        return "Maximum loans reached"
    if book["copies_available"] <= 0:
        return "No copies available"

    user["current_loans"] += 1
    book["copies_available"] -= 1
    return "2023-10-01"  # Fixed due date for verifiability

def get_user_loans(user_id: str) -> int:
    """Return the number of books currently borrowed by the user."""
    user = next((u for u in users if u["user_id"] == user_id), None)
    return user["current_loans"] if user else 0

