reservations = [
    {"user_id": "user1", "room_id": "deluxe_101", "check_in": "2024-06-28", "check_out": "2024-07-01"},
    {"user_id": "user2", "room_id": "standard_201", "check_in": "2024-07-02", "check_out": "2024-07-05"}
]

available_rooms = {
    "deluxe": ["deluxe_102", "deluxe_103"],
    "standard": ["standard_202", "standard_203"]
}

discount_codes = {
    "SUMMER20": 0.2,
    "WINTER15": 0.15
}

def get_available_rooms(check_in_date: str, check_out_date: str, room_type: str) -> list[str]:
    return available_rooms.get(room_type, [])

def get_room_price(room_id: str) -> float:
    return 150.0 if "deluxe" in room_id else 100.0

def calculate_total_price(room_id: str, nights: int) -> float:
    price = get_room_price(room_id)
    return price * nights

def apply_discount(total_price: float, discount_code: str) -> float:
    discount = discount_codes.get(discount_code, 0.0)
    return total_price * (1 - discount)

def create_reservation(user_id: str, room_id: str, check_in: str, check_out: str) -> bool:
    for reservation in reservations:
        if reservation["room_id"] == room_id:
            if (check_in < reservation["check_out"] and check_out > reservation["check_in"]):
                return False
    reservations.append({"user_id": user_id, "room_id": room_id, "check_in": check_in, "check_out": check_out})
    return True

