# Mocked data representing user accounts and transaction records
users = [
    {"id": 101, "name": "Alice Chen", "email": "alice@example.com", "balance": 1500},
    {"id": 102, "name": "Bob Wilson", "email": "bob@example.com", "balance": 2300},
    {"id": 103, "name": "Carol Davis", "email": "carol@example.com", "balance": 1800}
]

transactions = [
    {"user_id": 101, "type": "purchase", "amount": 300, "date": "2023-10-05"},
    {"user_id": 102, "type": "refund", "amount": 150, "date": "2023-10-06"},
    {"id": 103, "name": "Carol Davis", "email": "carol@example.com", "balance": 1800}
]

transactions = [
    {"user_id": 101, "type": "purchase", "amount": 300, "date": "2023-10-05"},
    {"user_id": 102, "type": "refund", "amount": 150, "date": "2023-10-06"},
    {"user_id": 101, "type": "purchase", "amount": 450, "date": "2023-10-07"},
    {"user_id": 103, "type": "transfer", "amount": 200, "date": "2023-10-08"}
]

from typing import List, Dict

def get_user_by_name(name: str) -> List[Dict]:
    """Find user details by partial name match"""
    return [user for user in users if name.lower() in user["name"].lower()]

def get_transactions(user_id: int, transaction_type: str = None) -> List[Dict]:
    """Retrieve transactions for a user, optionally filtered by type"""
    if transaction_type:
        return [t for t in transactions if t["user_id"] == user_id and t["type"] == transaction_type]
    return [t for t in transactions if t["user_id"] == user_id]

def calculate_total(transactions: List[Dict]) -> float:
    """Calculate sum of amounts from a list of transactions"""
    return sum(t["amount"] for t in transactions)

def update_balance(user_id: int, amount: float) -> bool:
    """Update user balance by specified amount (positive or negative)"""
    for user in users:
        if user["id"] == user_id:
            user["balance"] += amount
            return True
    return False

