# Mocked environment for travel planning system
from typing import List, Dict, TypedDict

class Flight(TypedDict):
    flight_id: str
    departure_city: str
    arrival_city: str
    date: str
    price: float

class Hotel(TypedDict):
    hotel_id: str
    name: str
    city: str
    check_in_date: str
    price_per_night: float
    stars: int

class Weather(TypedDict):
    date: str
    city: str
    temperature: float
    conditions: str

flights_db: List[Flight] = [
    {
        "flight_id": "FL123",
        "departure_city": "New York",
        "arrival_city": "London",
        "date": "2023-10-10",
        "price": 500.0
    },
    {
        "flight_id": "FL456",
        "departure_city": "New York",
        "arrival_city": "London",
        "date": "2023-10-10",
        "price": 600.0
    }
]

hotels_db: List[Hotel] = [
    {
        "hotel_id": "HTL101",
        "name": "Grand Plaza",
        "city": "London",
        "check_in_date": "2023-10-10",
        "price_per_night": 250.0,
        "stars": 4
    },
    {
        "hotel_id": "HTL102",
        "name": "Cozy Inn",
        "city": "London",
        "check_in_date": "2023-10-10",
        "price_per_night": 180.0,
        "stars": 4
    }
]

weather_db: List[Weather] = [
    {
        "date": "2023-10-10",
        "city": "London",
        "temperature": 15.5,
        "conditions": "sunny"
    },
    {
        "date": "2023-10-11",
        "city": "London",
        "temperature": 16.0,
        "conditions": "cloudy"
    },
    {
        "date": "2023-10-12",
        "city": "London",
        "temperature": 14.5,
        "conditions": "sunny"
    }
]

def search_flights(departure_city: str, arrival_city: str, date: str) -> List[Flight]:
    """Search for available flights between cities on specific date"""
    return [
        f for f in flights_db
        if f["departure_city"] == departure_city
        and f["arrival_city"] == arrival_city
        and f["date"] == date
    ]

def search_hotels(city: str, check_in_date: str, max_price_per_night: float, min_stars: int) -> List[Hotel]:
    """Find hotels matching location, date, price and quality criteria"""
    return [
        h for h in hotels_db
        if h["city"] == city
        and h["check_in_date"] == check_in_date
        and h["price_per_night"] <= max_price_per_night
        and h["stars"] >= min_stars
    ]

def get_weather_forecast(city: str, date: str) -> Weather:
    """Retrieve weather forecast for specific location and date"""
    return next(
        (w for w in weather_db if w["city"] == city and w["date"] == date),
        {"date": date, "city": city, "temperature": None, "conditions": "unknown"}
    )

def calculate_total_cost(flight_price: float, hotel_price_per_night: float, nights: int) -> float:
    """Calculate total trip cost including flight and accommodation"""
    return round(flight_price + hotel_price_per_night * nights, 2)

