def get_department_id(name: str) -> int:
    """Returns department ID for given department name"""
    for dept in departments:
        if dept["name"].lower() == name.lower():
            return dept["id"]
    return -1

def get_employees(department_id: int) -> list[int]:
    """Returns list of employee IDs in specified department"""
    return [emp["id"] for emp in employees if emp["department_id"] == department_id]

def get_projects(employee_id: int) -> list[dict]:
    """Returns project details for specified employee"""
    return [proj for proj in projects if proj["employee_id"] == employee_id]

def get_remaining_budget(department_id: int) -> float:
    """Calculates remaining budget for specified department"""
    dept = next(d for d in departments if d["id"] == department_id)
    used = sum(p["used_budget"] for emp in get_employees(department_id) for p in get_projects(emp))
