def get_products_by_category(category: str) -> list[dict]:
    return [product for product in products if product["category"] == category]

def calculate_total_sales(product_id: int, start_date: str, end_date: str) -> float:
    total = 0
    for record in sales_records:
        if (record["product_id"] == product_id and 
            start_date <= record["date"] <= end_date):
            total += record["quantity"]
    product = next(p for p in products if p["id"] == product_id)
    return total * product["price"]

def check_stock(product_id: int) -> int:
    product = next(p for p in products if p["id"] == product_id)
    return product["stock"]

def apply_discount_to_category(category: str, discount_percent: float) -> list[dict]:
    discounted_products = []
    for product in products:
        if product["category"] == category:
            discounted_price = round(product["price"] * (1 - discount_percent/100), 2)
            discounted_products.append({**product, "price": discounted_price})
    return discounted_products

