users = [
    {"user_id": 123, "name": "Alice", "loyalty_points": 150},
    {"user_id": 456, "name": "Bob", "loyalty_points": 75}
]

products = [
    {"product_id": 1, "name": "Laptop", "price": 25.0, "stock": 10},
    {"product_id": 2, "name": "Mouse", "price": 40.0, "stock": 5},
    {"product_id": 3, "name": "Keyboard", "price": 30.0, "stock": 8}
]

orders = []

def get_user(user_id: int) -> dict:
    """Return user details by user_id"""
    return next((u for u in users if u["user_id"] == user_id), None)

def get_product(product_id: int) -> dict:
    """Return product details by product_id"""
    return next((p for p in products if p["product_id"] == product_id), None)

def create_order(user_id: int, items: list[tuple[int, int]]) -> str:
    """Create new order with (product_id, quantity) pairs. Returns order ID."""
    order_id = f"ORD{len(orders)+1:03d}"
    orders.append({
        "order_id": order_id,
        "user_id": user_id,
        "items": items,
        "status": "CREATED"
    })
    return order_id

def calculate_order_total(order_id: str) -> float:
    """Calculate total amount for an order including any discounts"""
    order = next(o for o in orders if o["order_id"] == order_id)
    total = sum(get_product(p)["price"] * q for p, q in order["items"])

    user = get_user(order["user_id"])
    discount = min(user["loyalty_points"] // 10, 20)  # Max 20% discount
    return total * (1 - discount/100)

def apply_discount(order_id: str, discount_percent: float) -> None:
    """Apply percentage discount to an order (modifies order status)"""
    order = next(o for o in orders if o["order_id"] == order_id)
    order["status"] = f"DISCOUNT_APPLIED_{discount_percent}%"

def update_stock(product_id: int, quantity_sold: int) -> None:
    """Update product stock after order fulfillment"""
    product = next(p for p in products if p["product_id"] == product_id)
    product["stock"] -= quantity_sold

