def get_product_info(product_id: int) -> dict:
    """Return product details including price and stock"""
    return products.get(product_id, {})

def check_stock(product_id: int, quantity: int) -> bool:
    """Check if requested quantity is available in stock"""
    product = products.get(product_id)
    return product["stock"] >= quantity if product else False

def calculate_discount(user_id: int, total_price: float) -> float:
    """Calculate applicable discount based on membership status"""
    user = users.get(user_id)
    if user and user["membership"] == "premium":
        return round(total_price * 0.10, 2)
    if user and user["membership"] == "basic":
        return round(total_price * 0.05, 2)
    return 0.0

