]

def get_member_status(member_id: str) -> dict:
    """Check member status by ID"""
    return next((m for m in members if m["id"] == member_id), None)

def search_books(title: str = None, author: str = None, year: int = None) -> list:
    """Search books by title, author, or publication year"""
    results = books
    if title:
        results = [b for b in results if title.lower() in b["title"].lower()]
    if author:
        results = [b for b in results if author.lower() in b["author"].lower()]
    if year:
        results = [b for b in results if b["year"] == year]
    return results

def check_availability(book_id: str) -> bool:
    """Check if a book is available for reservation"""
    book = next((b for b in books if b["id"] == book_id), None)
    return book["available"] if book else False

def reserve_book(member_id: str, book_id: str) -> str:
    """Attempt to reserve a book for a member"""
    member = get_member_status(member_id)
    if not member or member["status"] != "active":
        return "Reservation failed: invalid or inactive member"

    if not check_availability(book_id):
        return "Reservation failed: book not available"

    book = next((b for b in books if b["id"] == book_id), None)
    if book:
        book["available"] = False
        return f"Reservation successful for book {book_id}"
    return "Reservation failed: book not found"

