from datetime import date
from typing import List, Dict, Optional, Tuple

class User:
    def __init__(self, user_id: int, name: str, checked_out: List[int]):
        self.user_id = user_id
        self.name = name
        self.checked_out = checked_out

class Book:
    def __init__(self, book_id: int, title: str, author: str, genre: str, available: bool):
        self.book_id = book_id
        self.title = title
        self.author = author
        self.genre = genre
        self.available = available

class Checkout:
    def __init__(self, user_id: int, book_id: int, due_date: str):
        self.user_id = user_id
        self.book_id = book_id
        self.due_date = due_date

users = [
    User(1, "Alice Smith", [101, 102]),
    User(2, "Bob Johnson", [103])
]

books = [
    Book(101, "The City and the Stars", "Arthur C. Clarke", "science fiction", False),
    Book(102, "2001: A Space Odyssey", "Arthur C. Clarke", "science fiction", False),
    Book(103, "Do Androids Dream of Electric Sheep?", "Philip K. Dick", "science fiction", True),
    Book(104, "Neuromancer", "William Gibson", "cyberpunk", True),
    Book(105, "Ubik", "Philip K. Dick", "science fiction", True)
]

checkouts = [
    Checkout(1, 101, "2023-10-01"),
    Checkout(1, 102, "2024-02-01"),
    Checkout(2, 103, "2024-01-20")
]

def get_user_by_name(name: str) -> Optional[User]:
    return next((u for u in users if u.name == name), None)

def search_books_by_author(author: str) -> List[Book]:
    return [b for b in books if b.author == author]

def search_books_by_genre(genre: str) -> List[Book]:
    return [b for b in books if b.genre == genre]

def checkout_book(user_id: int, book_id: int) -> str:
    book = next((b for b in books if b.book_id == book_id), None)
    user = next((u for u in users if u.user_id == user_id), None)

    if not book or not user:
        return "Invalid input"
    if not book.available:
        return "Book not available"

    book.available = False
    user.checked_out.append(book_id)
    checkouts.append(Checkout(user_id, book_id, str(date(2024, 1, 15) + date.resolution*14)))
    return "Checkout successful"

def list_overdue_books(current_date: str) -> List[Checkout]:
    return [c for c in checkouts if c.due_date < current_date]

