users = [
    {"user_id": "U123", "name": "Alice", "borrowed_books": ["1001"]},
    {"user_id": "U456", "name": "Bob", "borrowed_books": ["1002"]}
]

def search_books_by_author(author: str) -> list[dict]:
    """Return books filtered by author."""
    return [book for book in books if book["author"] == author]

def check_availability(isbn: str) -> int:
    """Return available copies count for a book."""
    book = next((b for b in books if b["isbn"] == isbn), None)
    return book["available_copies"] if book else 0

def reserve_book(user_id: str, isbn: str) -> bool:
    """Reserve a book if available and not reserved."""
    book = next((b for b in books if b["isbn"] == isbn), None)
    if book and book["available_copies"] > 0 and not book["is_reserved"]:
        book["is_reserved"] = True
        return True
    return False

def get_user_borrowed_books(user_id: str) -> list[dict]:
    """Return books currently borrowed by a user."""
    user = next((u for u in users if u["user_id"] == user_id), None)
    if not user:
        return []
    return [book for book in books if book["isbn"] in user["borrowed_books"]]

