# Mock library management environment
from datetime import datetime, timedelta

books = [
    {"title": "The Great Adventure", "isbn": "978-0553103540", "available": False, "due_date": datetime(2023, 12, 1)},
    {"title": "Data Science Basics", "isbn": "978-1492032649", "available": True, "due_date": None},
    {"title": "Python Fundamentals", "isbn": "978-1617294116", "available": False, "due_date": datetime(2023, 11, 15)},
    {"title": "Modern History", "isbn": "978-1400033423", "available": True, "due_date": None}
]

members = [
    {"member_id": 101, "name": "Alice Chen", "borrowed_count": 2, "has_penalty": True},
    {"member_id": 102, "name": "Bob Smith", "borrowed_count": 0, "has_penalty": False},
    {"member_id": 103, "name": "Carol Taylor", "borrowed_count": 1, "has_penalty": False}
]

def check_book_availability(isbn: str) -> bool:
    """Check if a book is available for borrowing"""
    book = next((b for b in books if b["isbn"] == isbn), None)
    return book["available"] if book else False

def check_member_status(member_id: int) -> tuple[int, bool]:
    """Get member's current borrowed count and penalty status"""
    member = next((m for m in members if m["member_id"] == member_id), None)
    return (member["borrowed_count"], member["has_penalty"]) if member else (0, True)

def borrow_book(isbn: str, member_id: int) -> str:
    """Attempt to borrow a book for a member"""
    book = next((b for b in books if b["isbn"] == isbn), None)
    member = next((m for m in members if m["member_id"] == member_id), None)

    if not book or not member:
        return "Invalid request"

    if book["available"] and not member["has_penalty"] and member["borrowed_count"] < 3:
        book["available"] = False
        member["borrowed_count"] += 1
        book["due_date"] = datetime.now() + timedelta(days=14)
        return "Success"
    return "Failed"

def calculate_overdue_fee(isbn: str) -> float:
    """Calculate overdue fees based on current date"""
    book = next((b for b in books if b["isbn"] == isbn), None)
    if not book or book["available"]:
        return 0.0

    overdue_days = (datetime.now() - book["due_date"]).days
    return max(0, overdue_days) * 0.50

