from dataclasses import dataclass
from typing import List

@dataclass
class Employee:
    id: int
    name: str
    department: str
    salary: float

@dataclass
class Project:
    project_id: int
    name: str
    team_size: int
    budget: float

employees = [
    Employee(1, "Alice", "Engineering", 120000),
    Employee(2, "Bob", "Engineering", 130000),
    Employee(3, "Charlie", "Marketing", 90000),
    Employee(4, "David", "Marketing", 95000),
    Employee(5, "Eve", "HR", 80000)
]

projects = [
    Project(101, "Alpha", 3, 500000),
    Project(102, "Beta", 5, 750000),
    Project(103, "Gamma", 4, 600000)
]

def get_all_departments() -> List[str]:
    return list({emp.department for emp in employees})

def get_employees_by_department(department: str) -> List[Employee]:
    return [emp for emp in employees if emp.department == department]

def calculate_average_salary(employees: List[Employee]) -> float:
    if not employees:
        return 0.0
    return sum(e.salary for e in employees) / len(employees)

def get_projects_by_min_team_size(min_team_size: int) -> List[Project]:
    return [p for p in projects if p.team_size >= min_team_size]

def calculate_total_budget(projects: List[Project]) -> float:
    return sum(p.budget for p in projects)

