    return 0

def check_renewal_possible(book_id: str, user_id: int) -> bool:
    for user in users:
        if user['id'] == user_id:
            for loan in user['loans']:
                if loan['book_id'] == book_id:
                    return loan['renewals_left'] > 0
    return False

def renew_loan(book_id: str, user_id: int) -> bool:
    for user in users:
        if user['id'] == user_id:
            for loan in user['loans']:
                if loan['book_id'] == book_id and loan['renewals_left'] > 0:
                    loan['renewals_left'] -= 1
                    return True
    return False

