    {"post_id": 4, "user_id": 456, "content": "Bob's Post", "likes": 100, "shares": 20, "timestamp": "2023-06-10 09:00:00"}
]

comments = [
    {"comment_id": i, "post_id": 1, "commenter_id": 456, "text": "Nice!", "timestamp": f"2023-06-01 10:{i:02d}:00"} for i in range(1,16)
] + [
    {"comment_id": i, "post_id": 2, "commenter_id": 789, "text": "Cool", "timestamp": f"2023-06-15 12:{i:02d}:00"} for i in range(16,24)
] + [
