    return [h for h in hotels if h["location"].lower() == location.lower()]

def check_availability(hotel_id: int, start_date: str, end_date: str) -> bool:
    conflicting = any(
        r["hotel_id"] == hotel_id and not (end_date <= r["start_date"] or start_date >= r["end_date"])
        for r in reservations
    )
    return not conflicting

def book_hotel(user_id: int, hotel_id: int, start_date: str, end_date: str) -> str:
    reservation = {
        "reservation_id": f"RES{len(reservations)+456}",
        "user_id": user_id,
        "hotel_id": hotel_id,
        "start_date": start_date,
        "end_date": end_date
    }
    reservations.append(reservation)
    return reservation["reservation_id"]

def get_user_reservations(user_id: int) -> list[dict]:
    return [r for r in reservations if r["user_id"] == user_id]

def calculate_total_price(hotel_id: int, nights: int) -> float:
    hotel = next(h for h in hotels if h["id"] == hotel_id)
    return hotel["price_per_night"] * nights

