from typing import List, Dict, Optional

flights = [
    {"id": "DL101", "from": "New York", "to": "London", "date": "2023-12-15", "seats": 5, "price": 600, "airline": "Delta"},
    {"id": "BA202", "from": "New York", "to": "London", "date": "2023-12-15", "seats": 3, "price": 650, "airline": "British"},
    {"id": "AA303", "from": "Chicago", "to": "Paris", "date": "2023-12-16", "seats": 7, "price": 550, "airline": "American"}
]

hotels = [
    {"id": "HILTON1", "name": "Hilton London", "location": "London", "check_in": "2023-12-15", "rooms": 4, "price_per_night": 200},
    {"id": "MARRIOT1", "name": "Marriott London", "location": "London", "check_in": "2023-12-15", "rooms": 0, "price_per_night": 220},
    {"id": "HILTON2", "name": "Hilton Paris", "location": "Paris", "check_in": "2023-12-16", "rooms": 5, "price_per_night": 180}
]

user_preferences = {"preferred_airlines": ["Delta"], "preferred_hotels": ["Hilton"]}

def search_flights(departure: str, destination: str, date: str) -> List[Dict]:
    """Search for available flights matching criteria"""
    return [f for f in flights if f["from"] == departure and f["to"] == destination and f["date"] == date]

def search_hotels(location: str, check_in: str) -> List[Dict]:
    """Find hotels in specified location with availability"""
    return [h for h in hotels if h["location"] == location and h["check_in"] == check_in and h["rooms"] > 0]

def check_flight_availability(flight_id: str) -> bool:
    """Verify if flight has available seats"""
    flight = next((f for f in flights if f["id"] == flight_id), None)
    return flight["seats"] > 0 if flight else False

def reserve_flight(flight_id: str, seats: int) -> Optional[str]:
    """Attempt to reserve seats on a flight"""
    flight = next((f for f in flights if f["id"] == flight_id), None)
    if flight and flight["seats"] >= seats:
        flight["seats"] -= seats
        return f"RESERVED_{flight_id}"
    return None

def book_hotel(hotel_id: str, nights: int) -> Optional[str]:
    """Attempt to book hotel room(s)"""
    hotel = next((h for h in hotels if h["id"] == hotel_id), None)
    if hotel and hotel["rooms"] > 0:
        hotel["rooms"] -= 1
        return f"BOOKED_{hotel_id}_FOR_{nights}_NIGHTS"
    return None

def get_user_preferences() -> Dict:
    """Retrieve user's travel preferences"""
    return user_preferences

