            'genre': 'sci-fi'
        }
    ],
    'users': [
        {
            'user_id': 'U123',
            'name': 'Alice',
            'active_reservations': []
        },
        {
            'user_id': 'U456',
            'name': 'Bob',
            'active_reservations': ['ISBN2']
        }
    ]
}

def search_books_by_title(title: str) -> List[Dict]:
    """Search books by title substring match"""
    return [b for b in mocked_data['books'] if title.lower() in b['title'].lower()]

def check_availability(isbn: str) -> bool:
    """Check if any copies are available for given ISBN"""
    book = next((b for b in mocked_data['books'] if b['isbn'] == isbn), None)
    return bool(book and book['available_copies'] > 0) if book else False

def reserve_book(user_id: str, isbn: str) -> str:
    """Reserve a book for user if available. Returns reservation ID or error"""
    user = next((u for u in mocked_data['users'] if u['user_id'] == user_id), None)
    if not user:
        return "User not found"

    book = next((b for b in mocked_data['books'] if b['isbn'] == isbn), None)
    if not book:
        return "Book not found"

    if book['available_copies'] > 0:
        reservation_id = f"RES-{isbn}-{user_id}"
        user['active_reservations'].append(reservation_id)
        book['available_copies'] -= 1
        return reservation_id
    return "No available copies"

def get_user_reservations(user_id: str) -> List[str]:
    """Get active reservation IDs for a user"""
    user = next((u for u in mocked_data['users'] if u['user_id'] == user_id), None)
    return user['active_reservations'].copy() if user else []

def find_related_books_by_genre(reference_isbn: str) -> List[Dict]:
    """Find books in same genre as reference ISBN"""
    ref_book = next((b for b in mocked_data['books'] if b['isbn'] == reference_isbn), None)
    if not ref_book:
        return []
    return [b for b in mocked_data['books'] 
            if b['genre'] == ref_book['genre'] 
            and b['isbn'] != reference_isbn]

