    employee_projects = [p for p in projects if p["employee_id"] == employee_id and p["status"] == "completed"]
    if len(employee_projects) < 3:
        return False
    avg_score = sum(p["score"] for p in employee_projects) / len(employee_projects)
    return avg_score >= 80

